    """Nature des sorties existantes : livraison de commande = vente, ajustement d'inventaire = non commerciale."""
    from stock.services.sortie_motif import est_sortie_commerciale

    Sortie = apps.get_model('stock', 'Sortie')
    InventaireSession = apps.get_model('stock', 'InventaireSession')
    Commande = apps.get_model('order', 'Commande')

    ajustements = set(
        InventaireSession.objects.exclude(sortie_ajustement=None).values_list('sortie_ajustement_id', flat=True)
    )
    livraisons = set(Commande.objects.exclude(sortie_livraison=None).values_list('sortie_livraison_id', flat=True))
    non_commerciales = [
        pk
        for pk, motif in Sortie.objects.values_list('pk', 'motif').iterator()
        if pk in ajustements or (pk not in livraisons and not est_sortie_commerciale(motif))
    ]
    for debut in range(0, len(non_commerciales), 500):
        Sortie.objects.filter(pk__in=non_commerciales[debut:debut + 500]).update(est_commerciale=False)


